                ['تغییر رمز یا موبایل کاربر توسط مدیر', 'با مجوز «ویرایش کاربر» + رمز فعلی خود مدیر', 'تغییر در گزارش رویدادها ثبت و از طریق ربات به کاربر اطلاع داده می‌شود؛ در حالت ورود به‌جای کاربر ممکن نیست.', null],
                ['دیدن و ویرایش تسک‌های پروژه', 'فقط تسک‌هایی که عضو در برد می‌بیند', 'دسترسی‌های نقش پروژه (ویرایش، یادداشت، …) فقط روی تسک‌های خودش و مسئولانِ انتخاب‌شده در «مشاهده‌ی تسک‌های» او اعمال می‌شود؛ دارنده‌ی «مشاهده‌ی تحلیل» بقیه را فقط می‌بیند. پیوست‌ها شماره‌ی آپلودکننده را نشان نمی‌دهند.', null],
                ['مسئول تسک پروژه', 'فقط اعضای همان پروژه', 'هنگام ساخت تسک، هر عضو پروژه (جز نقش «بدون دسترسی») و سازنده‌ی پروژه می‌تواند مسئول را از اعضای پروژه انتخاب کند؛ این قابل تنظیم نیست (v5.5). تغییر مسئولِ تسکِ ثبت‌شده مجوز «تغییر مسئول» می‌خواهد.', null],
                ['تیک «انجام شد»', 'ارسال به «بررسی سرپرست»؛ دارنده‌ی دسترسی تأیید = مستقیم «انجام‌شده»', 'مسئول، سازنده یا عضو دارای مجوز تکمیل/ارسال برای بررسی می‌تواند تیک بزند (بدون مجوز مرحله‌های میانی برد). از v5.4 اگر تیک‌زننده خودش دسترسی تأیید دارد (مجوز «تکمیل تسک» + مجوز برد «بررسی سرپرست ← انجام‌شده»، مثل سرپرست و سازنده‌ی پروژه)، تسک مستقیم «انجام‌شده» می‌شود (زمان تحویل و تأیید هر دو به نام خودش) و تیکش روی تسک منتظر تأیید = تأیید. پیام بعد از تیک دکمه‌ی «بازگردانی» دارد: تحویل‌دهنده تا قبل از تأیید پس می‌گیرد و تکمیل/تأیید تا ' . fa_num(\App\Services\BoardService::UNDO_DONE_MINUTES) . ' دقیقه برمی‌گردد. زمان انجام مسئول در KPI تا لحظه‌ی تحویل است و زمان تأیید جدا به نام سرپرست ثبت می‌شود.', null],
                ['تکمیل تسک پروژه', 'با تأیید در «بررسی سرپرست» یا تیک دارنده‌ی دسترسی تأیید', 'مجوز «تکمیل تسک» + مجوز برد «بررسی سرپرست ← انجام‌شده»؛ جابه‌جایی دستی در بورد هم فقط از «بررسی سرپرست» به «انجام‌شده» است. سقف ستون‌های برد هم رعایت می‌شود.', null],
                ['عقب‌افتاده و تأخیر', 'روزانه', 'عقب‌افتاده = سررسید روزهای قبل و هنوز تحویل نشده (TaskModel::OVERDUE؛ از v7.7 تسک تحویل‌شده‌ی منتظر تأیید سرپرست در هیچ‌جا عقب‌افتاده نیست؛ تسک امروزِ ساعت‌گذشته در «امروز» با برچسب «ساعت گذشته» می‌ماند)؛ تأخیر در KPI فقط وقتی روز اولین تحویل بعد از روز سررسید باشد. «امروز» در تقویم و انتخابگر تاریخ از ساعت سرور است، نه دستگاه.', null],
                ['سهمیه‌ی مصرف هوش مصنوعی (v7.21)', 'پیش‌فرض: روزانه ' . (($d = \App\Services\Karlix\Quota::defaults())['daily'] === null ? 'نامحدود' : fa_num(number_format($d['daily']))) . '، ماهانه ' . ($d['monthly'] === null ? 'نامحدود' : fa_num(number_format($d['monthly']))) . '، کلی ' . ($d['total'] === null ? 'نامحدود' : fa_num(number_format($d['total']))) . ' توکن؛ پاسخ بدون usage: ' . (\App\Services\Karlix\Quota::missingPolicy() === 'zero' ? 'صفر' : 'همان رزرو') . ' (AI_USAGE_MISSING)', 'همه‌ی بخش‌های هوش مصنوعی (کارلیکس یادداشت و دستیار بورد) فقط از Agnes::chat و Karlix\\Quota عبور می‌کنند: پیش از ارسال، رزرو (ورودی تخمینی + سقف خروجی) در تراکنش با قفل سهمیه‌ی کاربر و بررسی سقف روزانه (ساعت تهران)، ماهانه (ماه شمسی) و کلی؛ بعد از پاسخ، مصرف واقعی گزارش‌شده‌ی سرویس (prompt + completion توکن) یک بار ثبت می‌شود. خطای بدون پاسخ = صفر. سقف NULL = نامحدود. مدیر در «تنظیمات ← میزان مصرف» (دسترسی manage_ai_usage) سهمیه‌ی هر کاربر و پیش‌فرض را تعیین می‌کند؛ کاربر در «پروفایل ← میزان مصرف». سقف تعداد درخواست دقیقه‌ای/روزانه (AI_PER_MINUTE / AI_DAILY_LIMIT) هم مثل قبل جداگانه برقرار است. جدول‌ها: ai_quotas، ai_usage، ai_usage_counters.', null],
                ['لاگ خطاهای هوش مصنوعی و تلاش مجدد (v7.23)', 'پوشه‌ی storage/logs/AI (روزانه، نگهداری ' . fa_num(\App\Core\Log::retentionDays()) . ' روز)؛ کارلیکس یادداشت: ' . fa_num(\App\Services\Karlix\Assistant::RETRIES) . ' تلاش مجدد خودکار', 'هر درخواست ناموفق به هوش مصنوعی (هر دو دستیار) یک بلوک در storage/logs/AI/<تاریخ>.log دارد: زمان تهران و مدت، کد پیگیری و مسیر درخواست، کاربر (و مدیر واقعی در ورود به پنل کاربر)، بخش و شماره‌ی تلاش، علت خطا (کد، HTTP، توضیح)، پیام کاربر، درخواست ارسالی به مدل (بدون system prompt و تقویم) و جواب خام هوش مصنوعی؛ همه پاک‌سازی‌شده (کلید و توکن، موبایل و ایمیل ماسک). درخواست کارلیکس در یادداشت تسک بعد از خطای موقت (قطعی شبکه، زمان، خطای سرور، سقف سرویس، پاسخ نامفهوم) خودکار دو بار دیگر (۵ و ۲۰ ثانیه بعد) ارسال می‌شود — از صفحه‌ی تسک یا اگر بسته باشد از هر صفحه‌ی پنل؛ بعد از خطای سوم «کارلیکس» در گفتگوی کاربر پیام می‌دهد که درخواست با خطا روبه‌رو شد، با متن درخواست و دکمه‌ی «مشاهده‌ی تسک».', null],
                ['دستیار هوش مصنوعی بورد (v7.20، v7.22)', (\App\Services\Karlix\Agnes::enabled() ? 'فعال' : 'غیرفعال') . '؛ سهمیه‌ی مشترک با کارلیکس یادداشت‌ها؛ هر عملیات گروهی حداکثر ' . fa_num(\App\Services\TaskService::BULK_MAX) . ' تسک، ساخت از متن حداکثر ' . fa_num(\App\Services\Karlix\BoardOps::CREATE_MAX) . ' تسک؛ تأیید ' . fa_num(\App\Services\Karlix\BoardOps::CONFIRM_MINUTES) . ' دقیقه، بازگردانی ' . fa_num(\App\Services\Karlix\BoardOps::UNDO_HOURS) . ' ساعت، لینک خروجی ' . fa_num(\App\Services\Karlix\Export::minutes()) . ' دقیقه (AI_EXPORT_MINUTES)', 'دکمه‌ی «هوش مصنوعی» در نوار ابزار بورد: فقط تسک‌های همان پروژه که کاربر در بورد می‌بیند. ابزارهای فقط‌خواندنی (لیست، آمار، رتبه‌بندی اعضا و بار کاری وزنی، کارنامه‌ی هر نفر، تفکیک، ریسک تسک‌ها، صف بررسی، سرعت، تکراری‌ها، گزارش بازه‌ای با مقایسه) مستقیم از دیتابیس و جواب مستقیم سؤال از عددهای واقعی؛ پرامپت‌های آماده به تفکیک قابلیت فقط برای دسترسی‌های خود کاربر؛ کاربر گفتگوهای قبلی خودش را حذف می‌کند (تغییرات اعمال‌شده می‌ماند)؛ تغییرها همیشه اول پیش‌نمایش و فقط با کلیک «تأیید و اجرا» (توکن یک‌بارمصرف) از همان سرویس‌های پنل با دسترسی خود کاربر؛ قابل بازگردانی. در ورود مدیر به پنل کاربر با دسترسی کاربر و ثبت مدیر واقعی در لاگ ممیزی (ai.board.*). خروجی CSV/PDF بیرون از webroot با لینک امضاشده. جدول‌ها: ai_board_sessions، ai_board_messages، ai_result_sets، ai_actions، ai_exports.', null],
                ['صف، اجراکننده‌ی سرور و سهمیه زیر بار هم‌زمان (v7.26)', 'صف نوبتی: ' . (static function () { [$r, $w] = \App\Services\Karlix\Agnes::queueState(); return fa_num($r) . ' در حال اجرا، ' . fa_num($w) . ' منتظر'; })() . ' (حداکثر ' . fa_num(\App\Services\Karlix\Agnes::maxWaiting()) . ' منتظر)؛ اجراکننده‌ی سرور ' . (\App\Services\Karlix\Assistant::workerAlive() ? 'فعال' : 'اجرا نمی‌شود (cron bin/ai-worker.php)') . '؛ انقضای درخواست ' . fa_num(\App\Services\Karlix\Assistant::expireMinutes()) . ' دقیقه', 'فراخوانی‌های مدل به ترتیب ورود (FIFO، جدول ai_queue) اجرا می‌شوند؛ بیش از AI_MAX_WAITING منتظر = فوراً «شلوغ» و تلاش مجدد خودکار، تا worker های PHP پشت صف پر نشوند. با cron «* * * * * php bin/ai-worker.php --procs=4» درخواست‌های @کارلیکس در سرور اجرا می‌شوند (حتی با مرورگر بسته) و مرورگر فقط وضعیت را می‌پرسد؛ درخواستی که بیش از AI_REQUEST_EXPIRE_MINUTES در صف بماند «منقضی شد» می‌گیرد. فقط درخواست در حال اجرا روی همان تسک مانع درخواست بعدی است. پاسخ خطای سرویس (۴۲۹، ۵xx، ۴۰۱) بدون usage از سهمیه کم نمی‌شود (مصرف رزروشده فقط برای پاسخ موفق بدون usage طبق AI_USAGE_MISSING). بن‌بست دیتابیس در رزرو سهمیه تا ۳ بار خودکار تکرار می‌شود. وضعیت پرسیدن کارلیکس سقف ۱۵۰ در دقیقه دارد و فقط اجرای واقعی از سقف ۴۰ در دقیقه کم می‌کند؛ پیام ردشده با «پیام قبلی در حال پردازش است» از سقف دقیقه‌ای هوش مصنوعی کم نمی‌کند. اندازه‌ی استخر PHP-FPM: docs/DEPLOY.md.', null],
                ['هم‌زمانی و تلاش مجدد دستیار بورد (v7.24)', 'حداکثر ' . (\App\Services\Karlix\Agnes::concurrency() ? fa_num(\App\Services\Karlix\Agnes::concurrency()) : 'نامحدود') . ' فراخوانی هم‌زمان (AI_MAX_CONCURRENT)، صف تا ' . fa_num(max(1, min(60, (int) env('AI_QUEUE_SECONDS', 20)))) . ' ثانیه؛ دستیار بورد ' . fa_num(\App\Services\Karlix\BoardAgent::RETRIES) . ' تلاش مجدد', 'فراخوانی‌های هم‌زمان مدل در کل سرور (همه‌ی کاربران، هر دو دستیار) به AI_MAX_CONCURRENT محدود است و بقیه تا AI_QUEUE_SECONDS در صف می‌مانند تا سرویس با هجوم هم‌زمان خطای ۴۲۹ ندهد. درخواست دستیار بورد قفل نشست را آزاد می‌کند (بقیه‌ی صفحه‌های همان کاربر معطل نمی‌مانند) و با بسته شدن مرورگر یا Timeout پراکسی متوقف نمی‌شود؛ پاسخ با /board/ai/status بازیابی می‌شود. هر فراخوانی که با خطای موقت (قطعی ارتباط، Timeout، خطای سرور یا سقف سرویس، پاسخ خالی، صف پر) روبه‌رو شود تا ۳ بار دیگر (حدود ۱، ۳ و ۶ ثانیه بعد؛ برای ۴۲۹ طبق Retry-After) تکرار می‌شود و رابط «در حال تلاش مجدد (n از ۳)…» نشان می‌دهد؛ بعد از ۳ تلاش ناموفق پاسخ «خطا در اتصال به کارلیکس». علت واقعی (از جمله کلید نامعتبر سرویس) هرگز به کاربر گفته نمی‌شود و فقط در storage/logs/AI است. هر تلاش جداگانه از سهمیه کم می‌شود (به اندازه‌ی مصرف واقعی).', null],
                ['دستیار هوش مصنوعی کارلیکس (v7.19)', (\App\Services\Karlix\Agnes::enabled() ? 'فعال، مدل ' . \App\Services\Karlix\Agnes::model() : 'غیرفعال (AGNES_API_KEY خالی یا AI_ENABLED=false)') . '؛ هر کاربر ' . fa_num(\App\Services\Karlix\Assistant::perMinute()) . ' درخواست در دقیقه و ' . fa_num(\App\Services\Karlix\Assistant::perDay()) . ' در ۲۴ ساعت', 'با «@کارلیکس» در یادداشت تسک (فهرست منشن). فقط تسک همان یادداشت و فقط عنوان، توضیحات، سررسید، اولویت، لیبل (افزودن/برداشتن لیبل موجود)، مسئول و وضعیت؛ حذف تسک/پروژه، کاربران، نقش‌ها و دسترسی‌ها خارج از محدوده است. مدل فقط عملیات پیشنهاد می‌دهد؛ بک‌اند هر عملیات را از فهرست سفید اعتبارسنجی و با دسترسی خود درخواست‌کننده از همان سرویس‌های پنل اجرا می‌کند (دسترسی جدیدی ساخته نشده). «تکمیل کن» بدون مجوز تکمیل = ارسال برای «بررسی سرپرست» اگر مجاز باشد. خطای سرویس = هیچ تغییری. پاسخ = یادداشت کاربر ربات روی همان تسک (ویرایش‌نشدنی)، جدول ai_requests (هر یادداشت یک بار اجرا). زمان مجاز هر درخواست ' . fa_num(\App\Services\Karlix\Agnes::timeout()) . ' ثانیه (AI_TIMEOUT). فعلاً فقط از پنل وب، نه REST API.', null],
                ['صندوق بررسی سرپرست (v7.9)', 'مهلت بررسی ' . fa_num(\App\Services\ReviewService::slaHours()) . ' ساعت؛ تأیید گروهی حداکثر ' . fa_num(\App\Services\ReviewService::BULK_MAX), 'پیشخوان ← «ورود به صندوق بررسی»: همه‌ی تحویل‌های «بررسی سرپرست» که کاربر اجازه‌ی تأییدشان را دارد (مجوز تکمیل + انتقال review → done)، بیشترین انتظار اول. زمان انتظار از لحظه‌ی ورود به review (tasks.delivered_at)؛ مهلت با REVIEW_SLA_HOURS در .env. تأیید و برگشت ۵ ثانیه بعد فرستاده می‌شوند و «بازگردانی» در این فاصله درخواستی نمی‌فرستد. علت برگشت چند دسته‌ای (tasks.rework_category) + متن به‌صورت یادداشت. API: GET /reviews/pending و POST /reviews/bulk-approve. سقف ۶۰ درخواست در دقیقه.', null],
                ['بار کاری پروژه (v7.10)', 'ظرفیت ' . fa_num(\App\Services\WorkloadService::CAP_MIN) . ' تا ' . fa_num(\App\Services\WorkloadService::CAP_MAX) . ' امتیاز (پیش‌فرض ' . fa_num(\App\Services\WorkloadService::DEFAULTS['capacity']) . ')؛ حداکثر ' . fa_num(\App\Services\WorkloadService::DEFAULTS['max_suggestions']) . ' پیشنهاد', 'پروژه‌ها ← دکمه‌ی «بار کاری» روی کارت (سازنده یا «مشاهده‌ی تحلیل‌ها»). بار هر نفر = امتیاز تسک‌های باز (زیاد ' . fa_num(\App\Services\WorkloadService::DEFAULTS['weights']['high']) . '، متوسط ' . fa_num(\App\Services\WorkloadService::DEFAULTS['weights']['medium']) . '، کم ' . fa_num(\App\Services\WorkloadService::DEFAULTS['weights']['low']) . ') که عقب‌افتاده‌اند، تا ' . fa_num(\App\Services\WorkloadService::DEFAULTS['window_days']) . ' روز آینده سررسید دارند یا بدون سررسیدند؛ درصد = بار ÷ ظرفیت. ظرفیت پروژه projects.workload_capacity و ظرفیت اختصاصی عضو project_members.weekly_capacity (مودال دسترسی عضو ← تب بورد). سقف هم‌زمان عضو = کمترین «سقف تعداد تسک» او. پیشنهاد فقط تسک‌های شروع‌نشده را به عضو فعال غیر «بدون دسترسی» با بار ≤ ' . fa_num(\App\Services\WorkloadService::DEFAULTS['target_max']) . '٪ می‌دهد. اعمال، کشیدن و ظرفیت فقط برای سازنده یا دارنده‌ی «تغییر مسئول»؛ همان مسیر تغییر مسئول (تاریخچه با منبع، اعلان به مسئول جدید و قبلی). API: GET /projects/workload، POST /projects/workload/reassign و /capacity. سقف ۳۰ بارگذاری و ۶۰ جابه‌جایی در دقیقه.', null],
                ['تغییر گروهی تسک‌ها (v7.8)', 'حداکثر ' . fa_num(\App\Services\TaskService::BULK_MAX) . ' تسک در هر بار', 'در فهرست تسک‌ها و بورد (دکمه‌ی «تغییر گروهی»): وضعیت بورد (فقط وقتی همه در یک پروژه‌اند)، اولویت، مسئول (اعضای مشترک پروژه‌ها)، لیبل، پروژه و سررسید. هر تسک با همان دسترسی ویرایش تکی بررسی می‌شود؛ تسکی که اجازه ندارد تغییر نمی‌کند و در فهرست «تغییر نکردند» می‌آید. سقف ۳۰ درخواست در دقیقه.', null],
                ['حساب غیرفعال (v7.8)', 'فقط مشاهده', 'کاربری که مدیر «غیرفعال» کرده وارد پنل می‌شود و تسک‌ها، بورد، همکاران و گفتگوها را می‌بیند ولی هر ثبت یا تغییری (تسک، پیام، تغییر وضعیت، مدیریت پروژه، …) خطای ACCOUNT_INACTIVE می‌گیرد (API هم فقط GET). «مسدود» و «در انتظار تأیید» اصلاً وارد پنل نمی‌شوند. مجاز: خروج، تم دستگاه و تأیید یادآوری.', null],
